// Generated by node scripts/build-admin.mjs. Edit admin-parts, then regenerate.
const __base=new URL('../assets/js/', window.location.href);
const [{ blankQuiz, makeQuestion, PALETTE, TEMPLATES, OPTION_TYPES, RESPONSE_TYPES, uid },
  { listQuizzes, saveQuiz, deleteQuiz, resetDemo, getLocalState, saveGlobalSettings, storageMode },
  { firebaseEnabled },
  { waitForAuth, loginEmail, logout },
  { deepClone, escapeHtml, formatDate, slugify, toast, copyText, download, csvEscape, safeJson }] = await Promise.all([
  import(new URL('defaults.js',__base).href),
  import(new URL('repository.js',__base).href),
  import(new URL('firebase.js',__base).href),
  import(new URL('auth.js',__base).href),
  import(new URL('utils.js',__base).href)
]);

const content=document.getElementById('appContent');
const sideNav=document.getElementById('sideNav');
const titleEl=document.getElementById('viewTitle');
const subtitleEl=document.getElementById('viewSubtitle');
const storageBadge=document.getElementById('storageBadge');
const modalRoot=document.getElementById('modalRoot');
let quizzes=[];
let activeView='dashboard';
let editorQuiz=null;
let selectedFieldId=null;
let editorTab='questions';
let quizzesLastLoadedAt=0;

const viewMeta={
  dashboard:['Dashboard','Visão geral da operação'],quizzes:['Meus Quizzes','Gerencie seus quizzes e status'],editor:['Editor de Quiz','Crie e personalize sua experiência'],templates:['Templates','Modelos prontos para começar'],results:['Resultados','Respostas, scores e estatísticas'],settings:['Configurações','Identidade visual e preferências globais'],integrations:['Integrações','Tracking e integrações padrão']
};

function setPath(obj,path,value){const parts=path.split('.');let ref=obj;while(parts.length>1){const key=parts.shift();ref[key]=ref[key]??{};ref=ref[key];}ref[parts[0]]=value;}
function getPath(obj,path){return path.split('.').reduce((a,k)=>a?.[k],obj);}
function valueFromInput(el){if(el.type==='checkbox')return el.checked;if(el.type==='number'||el.type==='range')return el.value===''?null:Number(el.value);if(el.dataset.json==='true')return safeJson(el.value,{});return el.value;}
function statusLabel(status){return status==='published'?'<span class="status-pill success">Publicado</span>':status==='archived'?'<span class="status-pill muted">Arquivado</span>':'<span class="status-pill warning">Rascunho</span>';}
function uniqueSlug(value,currentId){let base=slugify(value)||`quiz-${Date.now().toString(36)}`;let candidate=base,n=2;while(quizzes.some(q=>q.id!==currentId&&q.slug===candidate))candidate=`${base}-${n++}`;return candidate;}

async function refresh(){quizzes=await listQuizzes({admin:true,includeSubmissions:true});quizzesLastLoadedAt=Date.now();storageBadge.textContent=await storageMode();storageBadge.className=`status-pill ${storageBadge.textContent==='Firebase'?'success':''}`;}
async function navigate(view,opts={}){activeView=view;sideNav.querySelectorAll('button[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));[titleEl.textContent,subtitleEl.textContent]=viewMeta[view]||['QuizPlatform',''];if(view==='editor'&&opts.quiz){editorQuiz=deepClone(opts.quiz);selectedFieldId=editorQuiz.questions?.[0]?.id||null;editorTab=opts.tab||'questions';}else if(view==='editor'&&!editorQuiz){editorQuiz=blankQuiz();selectedFieldId=editorQuiz.questions[0]?.id||null;}await render();document.getElementById('menuToggle').setAttribute('aria-expanded','false');document.getElementById('sidebar').classList.remove('open');}

async function render(){if(activeView!=='editor'&&(!quizzes.length||Date.now()-quizzesLastLoadedAt>15000))await refresh();if(activeView==='dashboard')renderDashboard();if(activeView==='quizzes')renderQuizzes();if(activeView==='editor')renderEditor();if(activeView==='templates')renderTemplates();if(activeView==='results')renderResults();if(activeView==='settings')renderSettings();if(activeView==='integrations')renderGlobalIntegrations();}

function renderDashboard(){
  const totals={quizzes:quizzes.length,responses:0,views:0};quizzes.forEach(q=>{totals.responses+=Number(q.statistics?.totalResponses)||q.submissions?.length||0;totals.views+=Number(q.statistics?.totalViews)||0;});
  const completion=totals.views?Math.min(100,Math.round((totals.responses/totals.views)*100)):0;
  const today=new Date().toISOString().slice(0,10);const newToday=quizzes.flatMap(q=>q.submissions||[]).filter(s=>String(s.createdAt||'').startsWith(today)).length;
  const recent=[...quizzes].sort((a,b)=>String(b.statistics?.updatedAt||'').localeCompare(String(a.statistics?.updatedAt||''))).slice(0,5);
  const popular=[...quizzes].sort((a,b)=>(b.statistics?.totalViews||0)-(a.statistics?.totalViews||0)).slice(0,5);
  const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-(6-i));return d.toISOString().slice(0,10);});
  const dayCounts=days.map(day=>quizzes.flatMap(q=>q.submissions||[]).filter(s=>String(s.createdAt||'').startsWith(day)).length);const max=Math.max(1,...dayCounts);
  content.innerHTML=`
    <div class="stats-grid">
      ${[['Quizzes criados',totals.quizzes],['Total de respostas',totals.responses],['Taxa de conclusão',`${completion}%`],['Novos hoje',newToday]].map(([l,v])=>`<article class="card stat-card"><div class="stat-value">${v}</div><div class="stat-label">${l}</div></article>`).join('')}
    </div>
    <div class="dashboard-grid">
      <section class="card card-pad"><div class="section-head"><div><h2>Últimos quizzes</h2><p>Atualizados recentemente</p></div><button class="btn btn-sm btn-secondary" data-go="quizzes">Ver todos</button></div><div class="list">${recent.length?recent.map(q=>`<div class="list-row"><div><strong>${escapeHtml(q.title)}</strong><small>${q.statistics?.totalResponses||q.submissions?.length||0} respostas · ${q.statistics?.completionRate||0}% conclusão</small></div><button class="btn btn-sm btn-ghost" data-edit="${q.id}">Editar</button></div>`).join(''):'<div class="empty">Nenhum quiz criado.</div>'}</div></section>
      <section class="card card-pad"><h2 style="margin:0;font-size:16px">Desempenho · 7 dias</h2><div class="chart-list">${days.map((d,i)=>`<div class="chart-col"><span style="height:${Math.max(8,(dayCounts[i]/max)*120)}px"></span><small>${d.slice(8)}</small></div>`).join('')}</div></section>
      <section class="card card-pad"><h2 style="margin:0 0 6px;font-size:16px">Quizzes mais populares</h2><div class="list">${popular.map(q=>`<div class="list-row"><div><strong>★ ${escapeHtml(q.title)}</strong><small>${q.statistics?.totalViews||0} visualizações</small></div><div style="width:110px"><div class="bar"><span style="width:${Math.min(100,((q.statistics?.totalViews||0)/Math.max(1,...popular.map(x=>x.statistics?.totalViews||0)))*100)}%"></span></div></div></div>`).join('')}</div></section>
      <section class="card card-pad"><h2 style="margin:0 0 12px;font-size:16px">Atalhos</h2><div class="actions"><button class="btn btn-primary" data-new>+ Novo Quiz</button><button class="btn btn-secondary" data-go="templates">Usar template</button><button class="btn btn-secondary" data-go="results">Ver resultados</button></div></section>
    </div>`;
  bindCommonActions();
}

function renderQuizzes(){
  content.innerHTML=`<div class="section-head"><div><h2>Meus Quizzes</h2><p>Busque, filtre, edite, publique ou duplique.</p></div><button class="btn btn-primary" id="newQuiz">+ Novo Quiz</button></div>
  <div class="toolbar"><div class="search"><input id="quizSearch" aria-label="Buscar quiz por título ou categoria" placeholder="Buscar quiz por título ou categoria"></div><select id="statusFilter" aria-label="Filtrar por status" class="btn btn-secondary"><option value="">Todos os status</option><option value="draft">Rascunho</option><option value="published">Publicado</option><option value="archived">Arquivado</option></select></div><div id="quizList"></div>`;
  const list=document.getElementById('quizList');
  const draw=()=>{const term=document.getElementById('quizSearch').value.toLowerCase();const status=document.getElementById('statusFilter').value;const filtered=quizzes.filter(q=>(!term||`${q.title} ${q.category}`.toLowerCase().includes(term))&&(!status||q.status===status));list.innerHTML=filtered.length?`<div class="quiz-grid">${filtered.map(q=>`<article class="card quiz-card"><div class="quiz-card-top"><div><h3>${escapeHtml(q.title)}</h3><div class="quiz-meta"><span>${escapeHtml(q.category||'Sem categoria')}</span><span>/quiz/?slug=${escapeHtml(q.slug)}</span></div></div>${statusLabel(q.status)}</div><div class="quiz-meta"><span>Respostas: ${q.statistics?.totalResponses||q.submissions?.length||0}</span><span>Atualizado: ${formatDate(q.statistics?.updatedAt)}</span></div><div class="quiz-actions"><button class="btn btn-sm btn-primary" data-edit="${q.id}">Editar</button><button class="btn btn-sm btn-secondary" data-preview="${q.id}">Visualizar</button><button class="btn btn-sm btn-secondary" data-publish="${q.id}">Publicar</button><button class="btn btn-sm btn-ghost" data-duplicate="${q.id}">Duplicar</button><button class="btn btn-sm btn-danger" data-delete="${q.id}">Excluir</button></div></article>`).join('')}</div>`:'<div class="card empty">Nenhum quiz encontrado.</div>';bindQuizCardActions();};

  document.getElementById('quizSearch').addEventListener('input',draw);document.getElementById('statusFilter').addEventListener('change',draw);document.getElementById('newQuiz').addEventListener('click',()=>startNew());draw();
}

function renderTemplates(){content.innerHTML=`<div class="section-head"><div><h2>Templates disponíveis</h2><p>Comece do zero ou use um modelo.</p></div><button class="btn btn-primary" id="blankTemplate">+ Criar do zero</button></div><div class="template-grid">${TEMPLATES.map((t,i)=>`<article class="card template-card"><div class="template-icon">${t.icon}</div><h3>${escapeHtml(t.title)}</h3><p>${escapeHtml(t.description)}</p><button class="btn btn-sm btn-secondary" data-template="${i}">Usar template</button></article>`).join('')}</div>`;document.getElementById('blankTemplate').onclick=()=>startNew();content.querySelectorAll('[data-template]').forEach(btn=>btn.onclick=()=>{const tpl=deepClone(TEMPLATES[Number(btn.dataset.template)].quiz);const q={...tpl,id:uid('quiz'),slug:uniqueSlug(tpl.title),title:tpl.title,status:'draft',statistics:{...tpl.statistics,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()},submissions:[]};navigate('editor',{quiz:q});});}

function startNew(){editorQuiz=blankQuiz();editorQuiz.slug=uniqueSlug(editorQuiz.title,editorQuiz.id);selectedFieldId=editorQuiz.questions[0]?.id||null;editorTab='questions';navigate('editor');}

function renderEditor(){
  if(!editorQuiz)editorQuiz=blankQuiz();
  content.innerHTML=`<div class="editor-topline"><input id="editorTitle" value="${escapeHtml(editorQuiz.title)}" aria-label="Título do quiz"><div class="actions"><button class="btn btn-secondary" id="saveDraft">Salvar</button><button class="btn btn-primary" id="publishQuiz">Publicar</button></div></div><div class="tabs">${[['config','Configurações'],['questions','Perguntas'],['design','Design'],['integrations','Integrações'],['results','Resultados']].map(([id,label])=>`<button class="tab ${editorTab===id?'active':''}" data-editor-tab="${id}">${label}</button>`).join('')}</div><div id="editorBody"></div>`;
  document.getElementById('editorTitle').addEventListener('input',e=>{editorQuiz.title=e.target.value;if(!editorQuiz.slug||editorQuiz.slug.startsWith('quiz-'))editorQuiz.slug=uniqueSlug(e.target.value,editorQuiz.id);});
  document.querySelectorAll('[data-editor-tab]').forEach(b=>b.onclick=()=>{editorTab=b.dataset.editorTab;renderEditor();});
  document.getElementById('saveDraft').onclick=()=>saveCurrent(false);document.getElementById('publishQuiz').onclick=()=>saveCurrent(true);
  if(editorTab==='questions')renderQuestionEditor();else if(editorTab==='config')renderConfigTab();else if(editorTab==='design')renderDesignTab();else if(editorTab==='integrations')renderIntegrationsTab();else renderResultTab();
}

function bindObjectForm(root,rerender=false){root.querySelectorAll('[data-path]').forEach(el=>{const handler=()=>{setPath(editorQuiz,el.dataset.path,valueFromInput(el));if(el.dataset.path==='title'&&!editorQuiz.slug)editorQuiz.slug=uniqueSlug(editorQuiz.title,editorQuiz.id);if(rerender)renderEditor();};el.addEventListener(el.type==='checkbox'||el.tagName==='SELECT'?'change':'input',handler);});}

function renderConfigTab(){const s=editorQuiz.settings,m=editorQuiz.messages,r=editorQuiz.resultSettings;if(s.showWelcome===undefined)s.showWelcome=true;document.getElementById('editorBody').innerHTML=`<div class="settings-grid"><section class="card settings-card"><h3>Informações gerais</h3><div class="form-grid"><div class="field full"><label>Descrição</label><textarea data-path="description">${escapeHtml(editorQuiz.description)}</textarea></div><div class="field"><label>Slug/URL</label><input data-path="slug" value="${escapeHtml(editorQuiz.slug)}"></div><div class="field"><label>Status</label><select data-path="status"><option value="draft" ${editorQuiz.status==='draft'?'selected':''}>Rascunho</option><option value="published" ${editorQuiz.status==='published'?'selected':''}>Publicado</option><option value="archived" ${editorQuiz.status==='archived'?'selected':''}>Arquivado</option></select></div><div class="field"><label>Categoria</label><input data-path="category" value="${escapeHtml(editorQuiz.category)}"></div><div class="field"><label>Tags (separadas por vírgula)</label><input id="tagsInput" value="${escapeHtml((editorQuiz.tags||[]).join(', '))}"></div></div></section>
  <section class="card settings-card"><h3>Comportamento</h3>${toggleRow('Mostrar boas-vindas (desative para pular a tela inicial)','settings.showWelcome',s.showWelcome!==false)}${toggleRow('Mostrar barra de progresso','settings.showProgress',s.showProgress)}${toggleRow('Mostrar número da pergunta','settings.showQuestionNumber',s.showQuestionNumber)}${toggleRow('Permitir voltar','settings.allowBack',s.allowBack)}${toggleRow('Salvar progresso automático','settings.autoSave',s.autoSave)}${toggleRow('Limitar respostas por IP/navegador','settings.limitByIp',s.limitByIp)}<div class="form-grid" style="margin-top:14px"><div class="field"><label>Tempo limite (min)</label><input type="number" min="0" data-path="settings.timeLimit" value="${s.timeLimit??''}"></div><div class="field"><label>Máximo de tentativas</label><input type="number" min="1" data-path="settings.maxAttempts" value="${s.maxAttempts??3}"></div></div></section>
  <section class="card settings-card"><h3>Mensagens personalizadas</h3><div class="field"><label>Boas-vindas</label><textarea data-path="messages.welcome">${escapeHtml(m.welcome)}</textarea></div><div class="field"><label>Erro de campo obrigatório</label><input data-path="messages.requiredError" value="${escapeHtml(m.requiredError)}"></div><div class="field"><label>Conclusão</label><textarea data-path="messages.completion">${escapeHtml(m.completion)}</textarea></div><div class="field"><label>Tempo esgotado</label><input data-path="messages.timeout" value="${escapeHtml(m.timeout)}"></div><div class="field"><label>Limite atingido</label><input data-path="messages.attemptLimit" value="${escapeHtml(m.attemptLimit)}"></div></section>
  <section class="card settings-card"><h3>Configuração de resultado</h3>${toggleRow('Mostrar porcentagem','resultSettings.showPercentage',r.showPercentage)}${toggleRow('Mostrar respostas corretas','resultSettings.showCorrectAnswers',r.showCorrectAnswers)}${toggleRow('Mostrar feedback por pergunta','resultSettings.showFeedback',r.showFeedback)}${toggleRow('Enviar resultado por email','resultSettings.emailResult',r.emailResult)}<div class="field" style="margin-top:14px"><label>Redirecionar após resultado</label><input data-path="resultSettings.redirectUrl" value="${escapeHtml(r.redirectUrl)}" placeholder="https://"></div><div class="field"><label>Email para envio</label><input data-path="resultSettings.resultEmail" value="${escapeHtml(r.resultEmail)}"></div></section></div>`;bindObjectForm(document.getElementById('editorBody'));document.getElementById('tagsInput').addEventListener('input',e=>editorQuiz.tags=e.target.value.split(',').map(x=>x.trim()).filter(Boolean));}
function toggleRow(label,path,checked){return `<div class="field-row"><span>${label}</span><label class="toggle"><input type="checkbox" data-path="${path}" ${checked?'checked':''}><span></span></label></div>`;}

function renderDesignTab(){const d=editorQuiz.design;const colors=[['Primária','primaryColor'],['Secundária','secondaryColor'],['Fundo','backgroundColor'],['Texto','textColor'],['Destaque','accentColor'],['Sucesso','successColor'],['Erro','errorColor']];document.getElementById('editorBody').innerHTML=`<div class="settings-grid"><section class="card settings-card"><h3>Cores</h3><div class="form-grid">${colors.map(([l,k])=>`<div class="field"><label>${l}</label><div class="color-field"><input type="color" data-path="design.${k}" value="${d[k]}"><input data-path="design.${k}" value="${d[k]}"></div></div>`).join('')}</div></section><section class="card settings-card"><h3>Tipografia</h3><div class="form-grid"><div class="field"><label>Fonte principal</label><select data-path="design.fontFamily">${['Poppins','Roboto','Inter','Montserrat','Arial'].map(f=>`<option ${d.fontFamily===f?'selected':''}>${f}</option>`).join('')}</select></div><div class="field"><label>Fonte dos títulos</label><select data-path="design.titleFont">${['Poppins','Roboto','Inter','Montserrat','Arial'].map(f=>`<option ${d.titleFont===f?'selected':''}>${f}</option>`).join('')}</select></div><div class="field"><label>Tamanho títulos</label><input type="number" data-path="design.titleSize" value="${d.titleSize}"></div><div class="field"><label>Peso títulos</label><select data-path="design.titleWeight"><option value="600" ${d.titleWeight==600?'selected':''}>600</option><option value="700" ${d.titleWeight==700?'selected':''}>700</option><option value="800" ${d.titleWeight==800?'selected':''}>800</option></select></div><div class="field"><label>Tamanho corpo</label><input type="number" data-path="design.bodySize" value="${d.bodySize}"></div><div class="field"><label>Peso corpo</label><select data-path="design.bodyWeight"><option value="400" ${d.bodyWeight==400?'selected':''}>Normal</option><option value="500" ${d.bodyWeight==500?'selected':''}>500</option><option value="600" ${d.bodyWeight==600?'selected':''}>600</option></select></div></div></section><section class="card settings-card"><h3>Fundo e logo</h3><div class="field"><label>Foto de perfil no topo (URL opcional)</label><input data-path="design.profileImage" value="${escapeHtml(d.profileImage||'')}"></div><div class="field"><label>Logo (URL)</label><input data-path="design.logo" value="${escapeHtml(d.logo)}"></div><div class="field"><label>Favicon (URL)</label><input data-path="design.favicon" value="${escapeHtml(d.favicon)}"></div><div class="field"><label>Imagem de fundo (URL)</label><input data-path="design.backgroundImage" value="${escapeHtml(d.backgroundImage)}"></div><div class="field"><label>Padrão de fundo (URL)</label><input data-path="design.backgroundPattern" value="${escapeHtml(d.backgroundPattern)}"></div></section><section class="card settings-card"><h3>Botões e cards</h3><div class="form-grid"><div class="field"><label>Botão fundo</label><input type="color" data-path="design.buttonBackground" value="${d.buttonBackground}"></div><div class="field"><label>Botão texto</label><input type="color" data-path="design.buttonText" value="${d.buttonText}"></div><div class="field"><label>Raio do botão</label><input type="number" data-path="design.buttonRadius" value="${d.buttonRadius}"></div><div class="field"><label>Raio do card</label><input type="number" data-path="design.cardRadius" value="${d.cardRadius}"></div><div class="field"><label>Padding do card</label><input type="number" data-path="design.cardPadding" value="${d.cardPadding}"></div></div>${toggleRow('Sombra no botão','design.buttonShadow',d.buttonShadow)}${toggleRow('Sombra no card','design.cardShadow',d.cardShadow)}</section></div>`;bindObjectForm(document.getElementById('editorBody'));}

function renderIntegrationsTab(){const i=editorQuiz.integrations;document.getElementById('editorBody').innerHTML=`<div class="integration-grid"><section class="card integration-card"><h3>Google Tag Manager</h3>${toggleRow('Ativado','integrations.gtmEnabled',i.gtmEnabled)}<div class="field"><label>ID</label><input data-path="integrations.gtmId" value="${escapeHtml(i.gtmId)}" placeholder="GTM-XXXXXX"></div></section><section class="card integration-card"><h3>Meta / Facebook Pixel</h3>${toggleRow('Ativado','integrations.fbPixelEnabled',i.fbPixelEnabled)}<div class="field"><label>Pixel ID</label><input data-path="integrations.fbPixelId" value="${escapeHtml(i.fbPixelId)}" placeholder="123456789012345"></div></section><section class="card integration-card"><h3>Google Analytics</h3>${toggleRow('Ativado','integrations.gaEnabled',i.gaEnabled)}<div class="field"><label>Measurement ID</label><input data-path="integrations.gaId" value="${escapeHtml(i.gaId)}" placeholder="G-XXXXXXXX"></div></section><section class="card integration-card"><h3>Email</h3><div class="field"><label>Enviar respostas para</label><input data-path="integrations.emailTo" value="${escapeHtml(i.emailTo)}"></div><div class="field"><label>Assunto</label><input data-path="integrations.emailSubject" value="${escapeHtml(i.emailSubject)}"></div><p class="muted" style="font-size:11px">O envio automático de email exige um endpoint/webhook ou função serverless.</p></section><section class="card integration-card"><h3>Webhook</h3><div class="field"><label>URL</label><input data-path="integrations.webhookUrl" value="${escapeHtml(i.webhookUrl)}" placeholder="https://api.exemplo.com/webhook"></div><div class="form-grid"><div class="field"><label>Método</label><select data-path="integrations.webhookMethod"><option ${i.webhookMethod==='POST'?'selected':''}>POST</option><option ${i.webhookMethod==='PUT'?'selected':''}>PUT</option></select></div><div class="field"><label>Headers JSON</label><input data-json="true" data-path="integrations.webhookHeaders" value='${escapeHtml(typeof i.webhookHeaders==='string'?i.webhookHeaders:JSON.stringify(i.webhookHeaders||{}))}'></div></div></section><section class="card integration-card"><h3>WhatsApp</h3><div class="field"><label>Número com DDI</label><input data-path="integrations.whatsappNumber" value="${escapeHtml(i.whatsappNumber)}" placeholder="5511999999999"></div><div class="field"><label>Mensagem</label><textarea data-path="integrations.whatsappMessage">${escapeHtml(i.whatsappMessage)}</textarea></div></section></div>`;bindObjectForm(document.getElementById('editorBody'));}

function renderResultTab(){editorQuiz.results=editorQuiz.results?.length?editorQuiz.results:[{id:uid('result'),minScore:0,maxScore:100,title:'Resultado',message:'Obrigado!',badge:'🏆',action:{type:'whatsapp',value:'',label:'Falar com Especialista'}}];const body=document.getElementById('editorBody');body.innerHTML=`<div class="section-head"><div><h2>Faixas de resultado</h2><p>Defina mensagens e ações conforme a pontuação.</p></div><button class="btn btn-secondary" id="addResult">+ Adicionar resultado</button></div><div style="display:grid;gap:14px">${editorQuiz.results.map((r,i)=>`<section class="card settings-card" data-result-index="${i}"><div class="section-head"><div><h2>${escapeHtml(r.title||`Resultado ${i+1}`)}</h2></div><button class="btn btn-sm btn-danger" data-remove-result="${i}">Remover</button></div><div class="form-grid"><div class="field"><label>Pontuação mínima</label><input type="number" data-result-path="minScore" value="${r.minScore}"></div><div class="field"><label>Pontuação máxima</label><input type="number" data-result-path="maxScore" value="${r.maxScore}"></div><div class="field"><label>Título</label><input data-result-path="title" value="${escapeHtml(r.title)}"></div><div class="field"><label>Badge</label><input data-result-path="badge" value="${escapeHtml(r.badge)}"></div><div class="field full"><label>Mensagem</label><textarea data-result-path="message">${escapeHtml(r.message)}</textarea></div><div class="field"><label>Ação</label><select data-result-path="action.type"><option value="whatsapp" ${r.action?.type==='whatsapp'?'selected':''}>WhatsApp</option><option value="email" ${r.action?.type==='email'?'selected':''}>Email</option><option value="link" ${r.action?.type==='link'?'selected':''}>Link</option></select></div><div class="field"><label>Valor da ação</label><input data-result-path="action.value" value="${escapeHtml(r.action?.value||'')}"></div><div class="field full"><label>Texto do botão</label><input data-result-path="action.label" value="${escapeHtml(r.action?.label||'')}"></div></div></section>`).join('')}</div>`;
  body.querySelectorAll('[data-result-index]').forEach(card=>{const idx=Number(card.dataset.resultIndex);card.querySelectorAll('[data-result-path]').forEach(el=>el.addEventListener(el.type==='number'?'input':'input',()=>{setPath(editorQuiz.results[idx],el.dataset.resultPath,valueFromInput(el));}));});body.querySelectorAll('[data-remove-result]').forEach(b=>b.onclick=()=>{editorQuiz.results.splice(Number(b.dataset.removeResult),1);renderResultTab();});document.getElementById('addResult').onclick=()=>{editorQuiz.results.push({id:uid('result'),minScore:0,maxScore:100,title:'Novo resultado',message:'Mensagem do resultado',badge:'🏆',action:{type:'whatsapp',value:'',label:'Falar com Especialista'}});renderResultTab();};}



function renderQuestionEditor(){const body=document.getElementById('editorBody');const selected=editorQuiz.questions.find(q=>q.id===selectedFieldId)||null;const groups=[...new Set(PALETTE.map(p=>p.group))];body.innerHTML=`<div class="editor-layout"><aside class="editor-panel"><h3>Paleta de componentes</h3><div class="palette">${groups.map(g=>`<div class="eyebrow" style="padding:6px 4px 2px">${g}</div>${PALETTE.filter(p=>p.group===g).map(p=>`<button draggable="true" class="palette-item" data-palette-type="${p.type}">${p.icon} ${p.label}</button>`).join('')}`).join('')}</div></aside><section class="editor-panel"><h3>Área de edição</h3><div class="editor-canvas"><div id="canvasDrop" class="canvas-drop">${editorQuiz.questions.length?editorQuiz.questions.map((q,i)=>questionBlock(q,i)).join(''):'<div class="empty">Arraste um componente para cá ou clique na paleta.</div>'}</div></div></section><aside class="editor-panel editor-properties"><h3>Propriedades</h3><div class="props" id="propsPanel">${selected?propertiesHtml(selected):'<p class="muted">Selecione um elemento.</p>'}</div></aside></div>`;
  bindQuestionEditorEvents();
}
function questionBlock(q,i){const p=PALETTE.find(x=>x.type===q.type);return `<article draggable="true" class="question-block ${q.id===selectedFieldId?'selected':''}" data-field-id="${q.id}"><div class="question-head"><div><strong>${p?.icon||'•'} ${escapeHtml(q.label||p?.label||q.type)}</strong><small>${escapeHtml(q.description||p?.label||q.type)}${q.required?' · obrigatório':''}</small></div><span class="drag-handle">⋮⋮</span></div>${q.options?.length?`<small class="muted">${q.options.map(o=>escapeHtml(o.label)).join(' · ')}</small>`:''}</article>`;}
function propertiesHtml(q){const optionText=(q.options||[]).map(o=>[o.label,o.value,o.weight??0,o.icon||'',o.image||''].join('|')).join('\n');const otherFields=editorQuiz.questions.filter(x=>x.id!==q.id&&RESPONSE_TYPES.has(x.type));const optionHelp=q.type==='image-options'?'Uma por linha: nome da imagem|valor|peso|ícone|URL da imagem':'Uma por linha: label|valor|peso|ícone|imagem';return `<div class="field"><label>ID do elemento</label><input data-qpath="id" value="${escapeHtml(q.id)}" disabled></div><div class="field"><label>Título/Label</label><input data-qpath="label" value="${escapeHtml(q.label)}"></div><div class="field"><label>Descrição/Placeholder</label><textarea data-qpath="description">${escapeHtml(q.description||'')}</textarea></div>${toggleQ('Obrigatório','required',q.required)}${toggleQ('Visível','visible',q.visible!==false)}<div class="field"><label>Valor padrão</label><input data-qpath="defaultValue" value="${escapeHtml(q.defaultValue||'')}"></div>${OPTION_TYPES.has(q.type)?`<h4>Opções</h4><div class="field"><label>${optionHelp}</label><textarea id="optionsEditor" style="min-height:150px">${escapeHtml(optionText)}</textarea>${q.type==='image-options'?'<small class="muted">O primeiro texto de cada linha é o nome que aparecerá junto da imagem.</small>':''}</div>${q.type==='checkbox'?toggleQ('Permitir múltipla escolha','multiple',q.multiple):''}${q.type==='image-options'?toggleQ('Avançar automaticamente ao clicar na imagem','autoAdvance',q.autoAdvance===true):''}`:''}${q.type==='image'?`<h4>Imagem</h4><div class="field"><label>URL da imagem</label><input data-qpath="imageUrl" value="${escapeHtml(q.imageUrl||'')}"></div><div class="field"><label>Texto alternativo</label><input data-qpath="alt" value="${escapeHtml(q.alt||'')}"></div><div class="field"><label>Object-fit</label><select data-qpath="objectFit"><option ${q.objectFit==='cover'?'selected':''}>cover</option><option ${q.objectFit==='contain'?'selected':''}>contain</option><option ${q.objectFit==='fill'?'selected':''}>fill</option></select></div>`:''}${q.type==='grid'?`<h4>Grid</h4><div class="field"><label>Colunas</label><select data-qpath="columns"><option ${q.columns==2?'selected':''}>2</option><option ${q.columns==3?'selected':''}>3</option><option ${q.columns==4?'selected':''}>4</option></select></div><div class="field"><label>Espaçamento</label><input type="number" data-qpath="gap" value="${q.gap||16}"></div>`:''}${['button','action'].includes(q.type)?`<h4>Ação</h4><div class="field"><label>Ação ao clicar</label><select data-qpath="actionType">${['next','submit','result','url','whatsapp','email','copy'].map(x=>`<option value="${x}" ${q.actionType===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Destino/valor</label><input data-qpath="actionValue" value="${escapeHtml(q.actionValue||'')}"></div>`:''}<h4>Estilo</h4><div class="form-grid"><div class="field"><label>Cor fundo</label><input type="color" data-qpath="style.backgroundColor" value="${q.style?.backgroundColor||'#FFFFFF'}"></div><div class="field"><label>Cor texto</label><input type="color" data-qpath="style.textColor" value="${q.style?.textColor||'#1F2937'}"></div><div class="field"><label>Fonte (px)</label><input type="number" min="12" max="48" data-qpath="style.fontSize" value="${q.style?.fontSize||16}"></div><div class="field"><label>Peso</label><select data-qpath="style.fontWeight"><option value="400" ${q.style?.fontWeight==400?'selected':''}>normal</option><option value="600" ${q.style?.fontWeight==600?'selected':''}>600</option><option value="700" ${q.style?.fontWeight==700?'selected':''}>700</option></select></div><div class="field"><label>Alinhamento</label><select data-qpath="style.align">${['left','center','right','justify'].map(x=>`<option ${q.style?.align===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Raio</label><input type="number" data-qpath="style.borderRadius" value="${q.style?.borderRadius||12}"></div></div><h4>Condição</h4><div class="field"><label>Mostrar/esconder conforme campo</label><select id="conditionField"><option value="">Sem condição</option>${otherFields.map(f=>`<option value="${f.id}" ${q.condition?.fieldId===f.id?'selected':''}>${escapeHtml(f.label)}</option>`).join('')}</select></div><div class="form-grid"><div class="field"><label>Regra</label><select id="conditionEffect"><option value="show" ${q.condition?.effect!=='hide'?'selected':''}>Mostrar se</option><option value="hide" ${q.condition?.effect==='hide'?'selected':''}>Esconder se</option></select></div><div class="field"><label>Operador</label><select id="conditionOperator">${['=','!=','>','<','contains'].map(x=>`<option value="${x}" ${q.condition?.operator===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field full"><label>Valor</label><input id="conditionValue" value="${escapeHtml(q.condition?.value||'')}"></div></div><button class="btn btn-danger btn-sm" id="removeField">Remover elemento</button>`;}
function toggleQ(label,path,checked){return `<div class="field-row"><span>${label}</span><label class="toggle"><input type="checkbox" data-qpath="${path}" ${checked?'checked':''}><span></span></label></div>`;}
function bindQuestionEditorEvents(){
  const canvas=document.getElementById('canvasDrop');let dragFieldId=null;
  document.querySelectorAll('[data-palette-type]').forEach(el=>{el.addEventListener('click',()=>addField(el.dataset.paletteType));el.addEventListener('dragstart',e=>{e.dataTransfer.setData('application/x-palette',el.dataset.paletteType);});});
  canvas.addEventListener('dragover',e=>{e.preventDefault();canvas.classList.add('dragover');});canvas.addEventListener('dragleave',()=>canvas.classList.remove('dragover'));canvas.addEventListener('drop',e=>{e.preventDefault();canvas.classList.remove('dragover');const type=e.dataTransfer.getData('application/x-palette');if(type){addField(type);return;}const moving=e.dataTransfer.getData('application/x-field');const target=e.target.closest('[data-field-id]')?.dataset.fieldId;if(moving&&target&&moving!==target){const from=editorQuiz.questions.findIndex(q=>q.id===moving),to=editorQuiz.questions.findIndex(q=>q.id===target);const [item]=editorQuiz.questions.splice(from,1);editorQuiz.questions.splice(to,0,item);renderQuestionEditor();}});
  canvas.querySelectorAll('[data-field-id]').forEach(el=>{el.addEventListener('click',()=>{selectedFieldId=el.dataset.fieldId;renderQuestionEditor();});el.addEventListener('dragstart',e=>{dragFieldId=el.dataset.fieldId;e.dataTransfer.setData('application/x-field',dragFieldId);});});
  const q=editorQuiz.questions.find(x=>x.id===selectedFieldId);if(!q)return;document.getElementById('propsPanel').querySelectorAll('[data-qpath]').forEach(el=>{const event=el.type==='checkbox'||el.tagName==='SELECT'?'change':'input';el.addEventListener(event,()=>setPath(q,el.dataset.qpath,valueFromInput(el)));});
  const optionsEditor=document.getElementById('optionsEditor');if(optionsEditor)optionsEditor.addEventListener('input',()=>{q.options=optionsEditor.value.split('\n').map(line=>line.trim()).filter(Boolean).map((line,i)=>{const [label,value,weight,icon,image]=line.split('|');return{id:q.options?.[i]?.id||uid('opt'),label:label?.trim()||`Opção ${i+1}`,value:(value?.trim()||slugify(label)||`opcao_${i+1}`),weight:Number(weight)||0,icon:icon?.trim()||'',image:image?.trim()||''};});});

  const cf=document.getElementById('conditionField');if(cf){const sync=()=>{if(!cf.value){q.condition=null;return;}q.condition={fieldId:cf.value,effect:document.getElementById('conditionEffect').value,operator:document.getElementById('conditionOperator').value,value:document.getElementById('conditionValue').value};};[cf,document.getElementById('conditionEffect'),document.getElementById('conditionOperator'),document.getElementById('conditionValue')].forEach(el=>el.addEventListener(el.tagName==='INPUT'?'input':'change',sync));}
  document.getElementById('removeField').onclick=()=>{editorQuiz.questions=editorQuiz.questions.filter(x=>x.id!==q.id);selectedFieldId=editorQuiz.questions[0]?.id||null;renderQuestionEditor();};
}
function addField(type){const p=PALETTE.find(x=>x.type===type);const q=makeQuestion(type,p?.label||'Novo elemento');editorQuiz.questions.push(q);selectedFieldId=q.id;renderQuestionEditor();}

async function saveCurrent(publish=false){
  const previousStatus=editorQuiz.status||'draft';
  editorQuiz.title=(editorQuiz.title||'Novo Quiz').trim();
  editorQuiz.slug=uniqueSlug(editorQuiz.slug||editorQuiz.title,editorQuiz.id);
  editorQuiz.status=publish?'published':previousStatus;
  editorQuiz.statistics=editorQuiz.statistics||{};
  editorQuiz.statistics.createdAt=editorQuiz.statistics.createdAt||new Date().toISOString();
  editorQuiz.statistics.updatedAt=new Date().toISOString();

  try{
    await saveQuiz(editorQuiz,{requireCloud:publish});
    toast(publish?'Quiz publicado e confirmado no Firebase.':'Alterações salvas.','success');
    if(publish){
      openPublishModal(editorQuiz);
      refresh().catch(error=>console.warn('Atualização do painel após publicar falhou.',error));
    }else{
      await refresh();
    }
  }catch(error){
    if(publish)editorQuiz.status=previousStatus;
    console.error('Falha ao salvar/publicar quiz.',error);
    toast(error?.message||'Não foi possível publicar o quiz.','error');
  }
}

function publicBase(){return new URL('../',window.location.href).href.replace(/\/$/,'');}
function quizUrl(q){return `${publicBase()}/quiz/?slug=${encodeURIComponent(q.slug)}`;}
function openPublishModal(q){const url=quizUrl(q);const embed=`<iframe src="${url}" width="100%" height="700" style="border:0;width:100%;" loading="lazy" allow="clipboard-write"></iframe>`;modalRoot.innerHTML=`<div class="modal-backdrop"><section class="modal"><div class="modal-head"><div><strong>Publicar Quiz</strong><div class="muted" style="font-size:12px">${escapeHtml(q.title)}</div></div><button class="icon-button" data-close>×</button></div><div class="modal-body publish-grid"><div class="field"><label>Link do quiz</label><div class="publish-row"><input readonly value="${escapeHtml(url)}"><button class="btn btn-secondary" data-copy="url">Copiar</button></div></div><div class="field"><label>Código embed</label><div class="code-box">${escapeHtml(embed)}</div><button class="btn btn-secondary btn-sm" data-copy="embed">Copiar código</button></div><div><label style="font-size:13px;font-weight:600">QR Code</label><div class="qr-preview" style="margin-top:8px"><img alt="QR Code" src="https://api.qrserver.com/v1/create-qr-code/?size=200x200&data=${encodeURIComponent(url)}"></div></div><div class="actions"><a class="btn btn-primary" href="${escapeHtml(url)}" target="_blank" rel="noopener">Visualizar Quiz</a><a class="btn btn-secondary" href="https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(url)}" target="_blank" rel="noopener">Facebook</a><a class="btn btn-secondary" href="https://www.linkedin.com/sharing/share-offsite/?url=${encodeURIComponent(url)}" target="_blank" rel="noopener">LinkedIn</a><a class="btn btn-secondary" href="https://wa.me/?text=${encodeURIComponent(url)}" target="_blank" rel="noopener">WhatsApp</a></div></div></section></div>`;modalRoot.querySelector('[data-close]').onclick=()=>modalRoot.innerHTML='';modalRoot.querySelector('[data-copy="url"]').onclick=async()=>{await copyText(url);toast('Link copiado.','success');};modalRoot.querySelector('[data-copy="embed"]').onclick=async()=>{await copyText(embed);toast('Código embed copiado.','success');};modalRoot.querySelector('.modal-backdrop').addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))modalRoot.innerHTML='';});}

function bindCommonActions(){content.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>navigate(b.dataset.go));content.querySelectorAll('[data-new]').forEach(b=>b.onclick=()=>startNew());content.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{const q=quizzes.find(x=>x.id===b.dataset.edit);if(q)navigate('editor',{quiz:q});});}
function bindQuizCardActions(){
  content.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>navigate('editor',{quiz:quizzes.find(q=>q.id===b.dataset.edit)}));
  content.querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>{const q=quizzes.find(x=>x.id===b.dataset.preview);window.open(quizUrl(q),'_blank','noopener');});
  content.querySelectorAll('[data-publish]').forEach(b=>b.onclick=async()=>{
    const q=quizzes.find(x=>x.id===b.dataset.publish);
    if(!q)return;
    const previousStatus=q.status||'draft';
    q.status='published';
    q.statistics=q.statistics||{};
    q.statistics.updatedAt=new Date().toISOString();
    try{
      await saveQuiz(q,{requireCloud:true});
      openPublishModal(q);
      toast('Quiz publicado e confirmado no Firebase.','success');
      refresh().then(()=>{if(activeView==='quizzes')renderQuizzes();}).catch(error=>console.warn('Atualização da lista após publicar falhou.',error));
    }catch(error){
      q.status=previousStatus;
      console.error('Falha ao publicar quiz pela lista.',error);
      toast(error?.message||'Não foi possível publicar o quiz.','error');
    }
  });
  content.querySelectorAll('[data-duplicate]').forEach(b=>b.onclick=async()=>{const src=quizzes.find(x=>x.id===b.dataset.duplicate);const q=deepClone(src);q.id=uid('quiz');q.title=`${src.title} - Cópia`;q.slug=uniqueSlug(q.title,q.id);q.status='draft';q.submissions=[];q.statistics={totalViews:0,totalResponses:0,completionRate:0,averageScore:0,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};await saveQuiz(q);toast('Quiz duplicado.','success');await refresh();renderQuizzes();});
  content.querySelectorAll('[data-delete]').forEach(b=>b.onclick=async()=>{const q=quizzes.find(x=>x.id===b.dataset.delete);if(confirm(`Excluir "${q.title}"?`)){await deleteQuiz(q.id);toast('Quiz excluído.');await refresh();renderQuizzes();}});
}


function renderResults(){const current=quizzes[0];content.innerHTML=`<div class="section-head"><div><h2>Resultados e estatísticas</h2><p>Visualize respostas por quiz e exporte os dados.</p></div><select id="resultQuizSelect" class="btn btn-secondary">${quizzes.map(q=>`<option value="${q.id}">${escapeHtml(q.title)}</option>`).join('')}</select></div><div id="resultBody"></div>`;const select=document.getElementById('resultQuizSelect');const draw=()=>{const q=quizzes.find(x=>x.id===select.value)||current;if(!q){document.getElementById('resultBody').innerHTML='<div class="card empty">Nenhum quiz disponível.</div>';return;}const subs=q.submissions||[];const views=Number(q.statistics?.totalViews)||0,responses=Number(q.statistics?.totalResponses)||subs.length,abandoned=Math.max(0,views-responses),completion=views?Math.round(responses/views*100):Number(q.statistics?.completionRate)||0,avg=Number(q.statistics?.averageScore)||0;const byQuestion=(q.questions||[]).filter(x=>OPTION_TYPES.has(x.type)).map(f=>{const counts={};subs.forEach(s=>{const v=s.answers?.[f.id];(Array.isArray(v)?v:[v]).filter(Boolean).forEach(x=>counts[x]=(counts[x]||0)+1);});return {field:f,counts};});document.getElementById('resultBody').innerHTML=`<div class="stats-grid"><article class="card stat-card"><div class="stat-value">${responses}</div><div class="stat-label">Total respostas</div></article><article class="card stat-card"><div class="stat-value">${completion}%</div><div class="stat-label">Taxa conclusão</div></article><article class="card stat-card"><div class="stat-value">${abandoned}</div><div class="stat-label">Abandonos estimados</div></article><article class="card stat-card"><div class="stat-value">${avg}%</div><div class="stat-label">Média de score</div></article></div><div class="dashboard-grid"><section class="card card-pad"><div class="section-head"><div><h2>Respostas por pergunta</h2></div></div>${byQuestion.length?byQuestion.map(({field,counts})=>`<div style="margin-bottom:18px"><strong style="font-size:13px">${escapeHtml(field.label)}</strong>${(field.options||[]).map(o=>{const n=counts[o.value]||0,p=responses?Math.round(n/responses*100):0;return `<div style="margin-top:8px"><div style="display:flex;justify-content:space-between;font-size:11px;color:var(--muted)"><span>${escapeHtml(o.label)}</span><span>${p}%</span></div><div class="bar"><span style="width:${p}%"></span></div></div>`;}).join('')}</div>`).join(''):'<p class="muted">Sem perguntas de opções.</p>'}</section><section class="card card-pad"><div class="section-head"><div><h2>Exportação</h2><p>${subs.length} registros disponíveis</p></div><button class="btn btn-secondary" id="exportCsv">Exportar CSV</button></div><div class="code-box">O CSV inclui ID, data, score, status e todas as respostas em JSON.</div></section></div><section class="card card-pad" style="margin-top:18px"><div class="section-head"><div><h2>Últimas respostas</h2></div></div><table class="result-table"><thead><tr><th>Identificação</th><th>Score</th><th>Data</th><th>Status</th></tr></thead><tbody>${subs.length?subs.slice(0,50).map(s=>`<tr><td>${escapeHtml(s.answers?.lead_name||s.answers?.name||s.id)}</td><td>${s.score??0}%</td><td>${formatDate(s.createdAt)}</td><td>${s.completed?'Concluído':'Incompleto'}</td></tr>`).join(''):'<tr><td colspan="4">Nenhuma resposta.</td></tr>'}</tbody></table></section>`;const exp=document.getElementById('exportCsv');if(exp)exp.onclick=()=>{const rows=[['id','createdAt','score','completed','answers'],...subs.map(s=>[s.id,s.createdAt,s.score,s.completed,JSON.stringify(s.answers||{})])];download(`${slugify(q.title)}-respostas.csv`,rows.map(r=>r.map(csvEscape).join(',')).join('\n'),'text/csv;charset=utf-8');};};if(current)select.value=current.id;select.addEventListener('change',draw);draw();}

function renderSettings(){const s=getLocalState().settings;content.innerHTML=`<div class="settings-grid"><section class="card settings-card"><h3>Identidade global</h3><div class="field"><label>Nome da plataforma</label><input id="globalName" value="${escapeHtml(s.platformName||'QuizPlatform')}"></div><div class="form-grid"><div class="field"><label>Cor primária</label><input id="globalPrimary" type="color" value="${s.primaryColor}"></div><div class="field"><label>Cor secundária</label><input id="globalSecondary" type="color" value="${s.secondaryColor}"></div></div><div class="field"><label>Fonte</label><select id="globalFont">${['Poppins','Roboto','Inter','Montserrat','Arial'].map(f=>`<option ${s.fontFamily===f?'selected':''}>${f}</option>`).join('')}</select></div><button class="btn btn-primary" id="saveGlobal">Salvar configurações</button></section><section class="card settings-card"><h3>Armazenamento</h3><p class="muted">Modo atual: <strong>${storageBadge.textContent}</strong>.</p><div class="code-box">assets/js/firebase-config.js</div><p class="muted" style="font-size:11px">O painel administrativo exige Firebase Authentication ativo. O quiz público pode continuar funcionando normalmente.</p></section></div>`;document.getElementById('saveGlobal').onclick=()=>{saveGlobalSettings({platformName:document.getElementById('globalName').value,primaryColor:document.getElementById('globalPrimary').value,secondaryColor:document.getElementById('globalSecondary').value,fontFamily:document.getElementById('globalFont').value});toast('Configurações salvas.','success');};}
function renderGlobalIntegrations(){const s=getLocalState().settings;content.innerHTML=`<div class="integration-grid"><section class="card integration-card"><h3>Google Tag Manager padrão</h3><div class="field"><label>ID</label><input id="globalGtm" value="${escapeHtml(s.gtmId||'')}" placeholder="GTM-XXXXXX"></div></section><section class="card integration-card"><h3>Meta Pixel padrão</h3><div class="field"><label>Pixel ID</label><input id="globalPixel" value="${escapeHtml(s.fbPixelId||'')}"></div></section><section class="card integration-card"><h3>Google Analytics padrão</h3><div class="field"><label>Measurement ID</label><input id="globalGa" value="${escapeHtml(s.gaId||'')}" placeholder="G-XXXXXXXX"></div></section><section class="card integration-card"><h3>Aplicar</h3><p class="muted">Estes IDs servem como padrão global. Cada quiz pode ter sua própria configuração na guia Integrações.</p><button class="btn btn-primary" id="saveInt">Salvar integrações</button></section></div>`;document.getElementById('saveInt').onclick=()=>{saveGlobalSettings({gtmId:document.getElementById('globalGtm').value.trim(),fbPixelId:document.getElementById('globalPixel').value.trim(),gaId:document.getElementById('globalGa').value.trim()});toast('Integrações padrão salvas.','success');};}

sideNav.addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(b)navigate(b.dataset.view);});document.getElementById('resetDemo').onclick=()=>{if(confirm('Restaurar os dados de demonstração? Isso substitui os dados locais deste navegador.')){resetDemo();editorQuiz=null;toast('Demonstração restaurada.','success');navigate('dashboard');}};
const logoutBtn=document.getElementById('logoutBtn');logoutBtn.style.display=firebaseEnabled()?'inline-block':'none';logoutBtn.onclick=async()=>{await logout();location.reload();};

async function requireLoginIfNeeded(){
  const authApi=await import(new URL('auth.js',__base).href);
  if(!firebaseEnabled()){
    modalRoot.innerHTML=`<div class="modal-backdrop"><section class="modal" style="max-width:500px"><div class="modal-head"><div><strong>Painel protegido</strong><div class="muted" style="font-size:12px">Autenticação ainda não configurada</div></div></div><div class="modal-body"><p>Por segurança, o painel administrativo está bloqueado até o Firebase Authentication ser ativado.</p><div class="code-box">Configure assets/js/firebase-config.js e ative Google + Email/Senha no Firebase.</div><p class="muted" style="font-size:12px">Administrador autorizado: <strong>${authApi.ADMIN_EMAIL}</strong></p></div></section></div>`;
    return false;
  }
  const user=await authApi.waitForAuth();
  if(user) return true;
  modalRoot.innerHTML=`<div class="modal-backdrop"><section class="modal" style="max-width:440px"><div class="modal-head"><div><strong>Acesso ao QuizPlatform</strong><div class="muted" style="font-size:12px">Painel administrativo protegido</div></div></div><div class="modal-body"><button id="googleLoginBtn" class="btn btn-secondary" style="width:100%;margin-bottom:14px" type="button">Entrar com Google</button><div style="display:flex;align-items:center;gap:10px;margin:4px 0 14px"><span style="height:1px;background:var(--border);flex:1"></span><small class="muted">ou</small><span style="height:1px;background:var(--border);flex:1"></span></div><form id="loginForm"><div class="field"><label>Email autorizado</label><input id="loginEmail" type="email" required autocomplete="username" value="${authApi.ADMIN_EMAIL}" readonly></div><div class="field"><label>Senha</label><input id="loginPassword" type="password" required autocomplete="current-password" placeholder="Digite sua senha"></div><p id="loginError" class="muted" style="font-size:12px"></p><button class="btn btn-primary" style="width:100%" type="submit">Entrar com email e senha</button></form></div></section></div>`;
  return await new Promise(resolve=>{
    const err=document.getElementById('loginError');
    document.getElementById('googleLoginBtn').onclick=async()=>{err.textContent='';try{await authApi.loginGoogle();modalRoot.innerHTML='';resolve(true);}catch(ex){err.textContent='Acesso negado. Entre com a conta Google wakilongestor@gmail.com.';console.error(ex);}};
    document.getElementById('loginForm').onsubmit=async e=>{e.preventDefault();err.textContent='';try{await authApi.loginEmail(authApi.ADMIN_EMAIL,document.getElementById('loginPassword').value);modalRoot.innerHTML='';resolve(true);}catch(ex){err.textContent='Não foi possível entrar. Confira a senha e se Email/Senha está habilitado no Firebase.';console.error(ex);}};
  });
}

const visualMemory=await import(new URL('platform-memory.js',__base).href);
function applyPlatformBrand(){const m=visualMemory.applyPlatformMemory();const brand=document.querySelector('.brand strong');if(brand)brand.textContent=m.platformName||'QuizPlatform';const mark=document.querySelector('.brand-mark');if(mark){if(m.logoData)mark.innerHTML=`<img src="${m.logoData}" alt="Logo" style="width:100%;height:100%;object-fit:contain;border-radius:inherit">`;else mark.textContent=(m.platformName||'Q').trim().charAt(0).toUpperCase()||'Q';}return m;}
applyPlatformBrand();
function visualMemoryFields(m){return `<div class="field"><label>Nome da plataforma</label><input id="memName" value="${escapeHtml(m.platformName)}" maxlength="60"></div><div class="form-grid"><div class="field"><label>Cor primária</label><input id="memPrimary" type="color" value="${m.primaryColor}"></div><div class="field"><label>Cor secundária</label><input id="memSecondary" type="color" value="${m.secondaryColor}"></div><div class="field"><label>Fundo</label><input id="memBackground" type="color" value="${m.backgroundColor}"></div><div class="field"><label>Cards</label><input id="memSurface" type="color" value="${m.surfaceColor}"></div><div class="field"><label>Texto</label><input id="memText" type="color" value="${m.textColor}"></div><div class="field"><label>Destaque</label><input id="memAccent" type="color" value="${m.accentColor}"></div></div><div class="form-grid"><div class="field"><label>Fonte</label><select id="memFont">${['Poppins','Roboto','Inter','Montserrat','Arial'].map(f=>`<option ${m.fontFamily===f?'selected':''}>${f}</option>`).join('')}</select></div><div class="field"><label>Raio dos cards</label><input id="memRadius" type="number" min="0" max="40" value="${m.radius}"></div></div><div class="form-grid"><div class="field"><label>Logo local</label><input id="memLogo" type="file" accept="image/*"></div><div class="field"><label>Favicon local</label><input id="memFavicon" type="file" accept="image/*"></div></div>`;}
function collectVisualMemory(){return {platformName:document.getElementById('memName').value.trim()||'QuizPlatform',primaryColor:document.getElementById('memPrimary').value,secondaryColor:document.getElementById('memSecondary').value,backgroundColor:document.getElementById('memBackground').value,surfaceColor:document.getElementById('memSurface').value,textColor:document.getElementById('memText').value,accentColor:document.getElementById('memAccent').value,fontFamily:document.getElementById('memFont').value,radius:Number(document.getElementById('memRadius').value)||14};}

async function renderSafeSettings(){
  const m=visualMemory.getPlatformMemory();const history=visualMemory.getPlatformHistory();
  content.innerHTML=`<div class="section-head"><div><h2>Identidade visual</h2><p>Memória local isolada. Esta tela não modifica Firebase nem integrações externas.</p></div><span class="status-pill success">Memória segura</span></div><div class="settings-grid"><section class="card settings-card"><h3>Marca e aparência</h3>${visualMemoryFields(m)}<div class="actions" style="margin-top:18px"><button class="btn btn-primary" id="saveMemory">Salvar identidade</button><button class="btn btn-secondary" id="undoMemory" ${history.length?'':'disabled'}>Desfazer última</button><button class="btn btn-ghost" id="resetMemory">Restaurar padrão</button></div></section><section class="card settings-card"><h3>Memória e segurança</h3><div class="code-box">Armazenamento: navegador local · sem Firestore</div><p class="muted" style="font-size:12px">Esta memória aceita somente nome, logo, favicon, cores, fonte, bordas e aparência. Firebase, autenticação, GTM, Pixel, Analytics, webhook e WhatsApp ficam fora dela.</p><div class="actions" style="margin-top:14px"><button class="btn btn-secondary" id="exportMemory">Exportar backup</button><label class="btn btn-secondary" style="cursor:pointer">Importar backup<input id="importMemory" type="file" accept="application/json" hidden></label></div><h3 style="margin-top:22px">Histórico</h3><div class="list">${history.length?history.slice(0,5).map((h,i)=>`<div class="list-row"><div><strong>${escapeHtml(h.platformName||'QuizPlatform')}</strong><small>${h.updatedAt?formatDate(h.updatedAt):'Versão anterior'}</small></div><button class="btn btn-sm btn-ghost" data-restore-memory="${i}">Restaurar</button></div>`).join(''):'<div class="empty">O histórico aparecerá após a primeira alteração.</div>'}</div><div class="card" style="padding:16px;margin-top:18px;background:var(--background)"><strong>Área crítica protegida</strong><p class="muted" style="font-size:12px;margin-bottom:0">A identidade visual não grava nem altera os vínculos externos da plataforma.</p></div></section></div>`;
  document.getElementById('saveMemory').onclick=async()=>{try{const patch=collectVisualMemory();const logo=document.getElementById('memLogo').files[0],favicon=document.getElementById('memFavicon').files[0];if(logo)patch.logoData=await visualMemory.fileToDataUrl(logo);if(favicon)patch.faviconData=await visualMemory.fileToDataUrl(favicon);visualMemory.savePlatformMemory(patch);applyPlatformBrand();toast('Identidade salva somente na memória local.','success');renderSafeSettings();}catch(e){toast(e.message||'Não foi possível salvar.','error');}};
  document.getElementById('undoMemory').onclick=()=>{if(visualMemory.restorePlatformMemory(0)){applyPlatformBrand();toast('Última versão restaurada.','success');renderSafeSettings();}};
  document.getElementById('resetMemory').onclick=()=>{if(confirm('Restaurar a identidade visual padrão?')){visualMemory.resetPlatformMemory();applyPlatformBrand();toast('Identidade padrão restaurada.','success');renderSafeSettings();}};
  document.getElementById('exportMemory').onclick=()=>download('quizplatform-identidade-visual.json',visualMemory.exportPlatformMemory(),'application/json');
  document.getElementById('importMemory').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;visualMemory.importPlatformMemory(await file.text());applyPlatformBrand();toast('Backup visual importado.','success');renderSafeSettings();}catch(err){toast(err.message||'Backup inválido.','error');}};
  content.querySelectorAll('[data-restore-memory]').forEach(btn=>btn.onclick=()=>{visualMemory.restorePlatformMemory(Number(btn.dataset.restoreMemory));applyPlatformBrand();toast('Versão restaurada.','success');renderSafeSettings();});
  ['memName','memPrimary','memSecondary','memBackground','memSurface','memText','memAccent','memFont','memRadius'].forEach(id=>document.getElementById(id).addEventListener('input',()=>{visualMemory.applyPlatformMemory({...m,...collectVisualMemory()});applyPlatformBrand();}));
}
renderSettings=renderSafeSettings;

const safeSettingsApi=await import(new URL('platform-safe-settings.js',__base).href);
const imageTools=await import(new URL('image-tools.js',__base).href);
const quizAssetsApi=await import(new URL('quiz-local-assets.js',__base).href);
const bpcTeaApi=await import(new URL('template-bpc-tea.js?v=tea15-20260820-2',__base).href);
const advogadoPrevidenciarioApi=await import(new URL('template-advogado-previdenciario.js',__base).href);
const incapacidadeNegadoApi=await import(new URL('template-incapacidade-negado.js?v=prev-20260820-1',__base).href);
const aposentadoriaRuralApi=await import(new URL('template-aposentadoria-rural.js?v=prev-20260820-1',__base).href);
if(!TEMPLATES.some(t=>t.id==='template_advogado_previdenciario'))TEMPLATES.unshift(advogadoPrevidenciarioApi.createAdvogadoPrevidenciarioTemplate());
if(!TEMPLATES.some(t=>t.id==='template_bpc_tea'))TEMPLATES.unshift(bpcTeaApi.createBpcTeaTemplate());
if(!TEMPLATES.some(t=>t.id==='template_incapacidade_negado'))TEMPLATES.unshift(incapacidadeNegadoApi.createIncapacidadeNegadoTemplate());
if(!TEMPLATES.some(t=>t.id==='template_aposentadoria_rural'))TEMPLATES.unshift(aposentadoriaRuralApi.createAposentadoriaRuralTemplate());

function applyActiveProfile(){const p=safeSettingsApi.getActiveProfile();const avatar=document.querySelector('.avatar');if(avatar){if(p?.photoData)avatar.innerHTML=`<img src="${p.photoData}" alt="Perfil" style="width:100%;height:100%;object-fit:cover;border-radius:50%">`;else avatar.textContent=(p?.name||'WG').split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase();avatar.title=`${p?.name||'Usuário'} · ${p?.role||'Perfil local'}`;}const brandMark=document.querySelector('.brand-mark');if(brandMark&&p?.panelLogoData)brandMark.innerHTML=`<img src="${p.panelLogoData}" alt="Logo" style="width:100%;height:100%;object-fit:contain;border-radius:inherit">`;}
applyActiveProfile();

function customQuizUrl(q){
  const custom=safeSettingsApi.getQuizDomain(q.id);
  if(!custom)return '';
  try{
    const u=new URL(custom);
    if(!u.searchParams.has('slug'))u.searchParams.set('slug',q.slug);
    return u.href;
  }catch{return '';}
}

function openDraftPreview(){try{const draft=quizAssetsApi.applyAssetsToPreview(deepClone(editorQuiz));sessionStorage.setItem('qp_preview_draft',JSON.stringify(draft));const url=`${publicBase()}/preview/`;modalRoot.innerHTML=`<div class="modal-backdrop"><section class="modal" style="width:min(1180px,96vw);max-height:94vh"><div class="modal-head"><div><strong>Pré-visualização do rascunho</strong><div class="muted" style="font-size:12px">Não salva respostas nem dispara integrações.</div></div><div class="actions"><button class="btn btn-sm btn-secondary" id="previewMobile">Mobile</button><button class="btn btn-sm btn-secondary" id="previewDesktop">Desktop</button><button class="icon-button" data-close-preview>×</button></div></div><div class="modal-body" style="background:#e2e8f0;display:grid;place-items:center"><iframe id="draftPreviewFrame" src="${url}" title="Pré-visualização" style="width:100%;height:720px;border:0;border-radius:14px;background:#fff"></iframe></div></section></div>`;const frame=document.getElementById('draftPreviewFrame');document.getElementById('previewMobile').onclick=()=>{frame.style.width='390px';};document.getElementById('previewDesktop').onclick=()=>{frame.style.width='100%';};modalRoot.querySelector('[data-close-preview]').onclick=()=>modalRoot.innerHTML='';}catch(e){toast(`Não foi possível abrir o preview: ${e.message}`,'error');}}

const _renderEditorBase=renderEditor;
renderEditor=function(){_renderEditorBase();const line=document.querySelector('.editor-topline');if(!line)return;const actions=line.querySelector('.actions');if(!document.getElementById('editorBack')){const back=document.createElement('button');back.id='editorBack';back.className='btn btn-secondary';back.textContent='← Voltar';back.onclick=()=>navigate('quizzes');line.insertBefore(back,line.firstChild);}if(actions&&!document.getElementById('previewDraft')){const preview=document.createElement('button');preview.id='previewDraft';preview.className='btn btn-secondary';preview.textContent='Pré-visualizar';preview.onclick=openDraftPreview;actions.insertBefore(preview,actions.firstChild);}};

const _renderConfigTabBase=renderConfigTab;
renderConfigTab=function(){_renderConfigTabBase();const body=document.getElementById('editorBody');if(!body)return;const custom=safeSettingsApi.getQuizDomain(editorQuiz.id);const section=document.createElement('section');section.className='card settings-card';section.innerHTML=`<h3>Domínio e endereço do quiz</h3><div class="field"><label>Domínio/endereço preferido</label><input id="quizCustomDomain" value="${escapeHtml(custom)}" placeholder="https://quiz.seudominio.com/"><small class="muted">Este endereço é salvo como referência. O link oficial publicado continua sendo gerado pela própria plataforma.</small></div><div class="actions" style="margin-top:12px"><button class="btn btn-secondary" id="saveQuizDomain">Salvar endereço local</button><button class="btn btn-ghost" id="clearQuizDomain">Remover</button></div>`;body.querySelector('.settings-grid')?.appendChild(section);document.getElementById('saveQuizDomain').onclick=()=>{try{safeSettingsApi.setQuizDomain(editorQuiz.id,document.getElementById('quizCustomDomain').value.trim());toast('Endereço preferido salvo localmente.','success');}catch(e){toast(e.message,'error');}};document.getElementById('clearQuizDomain').onclick=()=>{safeSettingsApi.setQuizDomain(editorQuiz.id,'');document.getElementById('quizCustomDomain').value='';toast('Endereço personalizado removido.','success');};};

function colorCard(label,key,description,d){const value=d[key]||'#000000';return `<div class="card" style="padding:14px;box-shadow:none"><div style="display:flex;align-items:center;gap:12px"><input type="color" data-design-color="${key}" value="${value}" style="width:54px;height:54px;padding:3px;border:1px solid var(--border);border-radius:12px;background:white"><div style="flex:1"><strong>${label}</strong><small class="muted" style="display:block">${description}</small><input data-design-hex="${key}" value="${value}" maxlength="7" style="margin-top:7px;width:110px;border:1px solid var(--border);border-radius:8px;padding:7px"></div><span data-color-sample="${key}" style="width:38px;height:38px;border-radius:10px;background:${value};border:1px solid var(--border)"></span></div></div>`;}
const _renderDesignTabBase=renderDesignTab;
renderDesignTab=function(){_renderDesignTabBase();const body=document.getElementById('editorBody');if(!body)return;const d=editorQuiz.design||{};const grid=body.querySelector('.settings-grid');const first=grid?.querySelector('section');if(first)first.style.display='none';const palette=document.createElement('section');palette.className='card settings-card';palette.innerHTML=`<h3>Paleta visual interativa</h3><p class="muted" style="font-size:12px">Cada cor mostra onde é usada e o código HEX exato.</p><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:10px">${[
['Cor primária','primaryColor','Botões principais e destaques'],['Cor secundária','secondaryColor','Ações secundárias e progresso'],['Fundo geral','backgroundColor','Fundo das páginas do quiz'],['Texto','textColor','Títulos e textos principais'],['Destaque','accentColor','Elementos de atenção'],['Sucesso','successColor','Confirmações e estados positivos'],['Erro','errorColor','Mensagens de erro e alertas']].map(x=>colorCard(x[0],x[1],x[2],d)).join('')}</div>`;grid?.insertBefore(palette,grid.firstChild);palette.querySelectorAll('[data-design-color]').forEach(input=>{input.oninput=()=>{const k=input.dataset.designColor;editorQuiz.design[k]=input.value;const hex=palette.querySelector(`[data-design-hex="${k}"]`),sample=palette.querySelector(`[data-color-sample="${k}"]`);if(hex)hex.value=input.value;if(sample)sample.style.background=input.value;};});palette.querySelectorAll('[data-design-hex]').forEach(input=>{input.onchange=()=>{const k=input.dataset.designHex;const v=input.value.trim();if(!/^#[0-9A-Fa-f]{6}$/.test(v)){toast(`Cor inválida em ${k}. Use formato HEX, por exemplo #1E3A8A.`,'error');input.value=editorQuiz.design[k]||'#000000';return;}editorQuiz.design[k]=v;const color=palette.querySelector(`[data-design-color="${k}"]`),sample=palette.querySelector(`[data-color-sample="${k}"]`);if(color)color.value=v;if(sample)sample.style.background=v;};});
const assets=quizAssetsApi.getQuizAssets(editorQuiz.id);const upload=document.createElement('section');upload.className='card settings-card';upload.innerHTML=`<h3>Imagens locais do quiz</h3><p class="muted" style="font-size:12px">Uploads usados no editor e na pré-visualização sem enviar arquivos ao Firebase.</p><div class="form-grid"><div class="field"><label>Logo do quiz</label><input id="localQuizLogo" type="file" accept="image/jpeg,image/png,image/webp"><small class="muted">${imageTools.imageHint('quizLogo')}</small>${assets.logoData?`<img src="${assets.logoData}" alt="Logo atual" style="max-width:160px;max-height:80px;object-fit:contain;margin-top:8px">`:''}</div><div class="field"><label>Favicon</label><input id="localQuizFavicon" type="file" accept="image/png,image/webp"><small class="muted">${imageTools.imageHint('favicon')}</small>${assets.faviconData?`<img src="${assets.faviconData}" alt="Favicon atual" style="width:48px;height:48px;object-fit:contain;margin-top:8px">`:''}</div><div class="field full"><label>Imagem de fundo</label><input id="localQuizBackground" type="file" accept="image/jpeg,image/png,image/webp"><small class="muted">${imageTools.imageHint('background')}</small>${assets.backgroundData?`<img src="${assets.backgroundData}" alt="Fundo atual" style="width:220px;height:100px;object-fit:cover;border-radius:10px;margin-top:8px">`:''}</div></div><div class="code-box" style="margin-top:14px">Esses arquivos ficam apenas neste navegador. O preview usa as imagens imediatamente e não altera Firebase/Storage.</div>`;grid?.appendChild(upload);
const uploadOne=async(id,type,key)=>{const el=document.getElementById(id);el.onchange=async()=>{try{const result=await imageTools.validateImageFile(el.files[0],type);quizAssetsApi.saveQuizAssets(editorQuiz.id,{[key]:result.dataUrl});toast(`${imageTools.IMAGE_LIMITS[type].label} salva para pré-visualização local.`,'success');renderDesignTab();}catch(e){toast(e.message,'error');el.value='';}};};uploadOne('localQuizLogo','quizLogo','logoData');uploadOne('localQuizFavicon','favicon','faviconData');uploadOne('localQuizBackground','background','backgroundData');};

const _renderQuestionEditorBase=renderQuestionEditor;
renderQuestionEditor=function(){_renderQuestionEditorBase();const q=editorQuiz.questions.find(x=>x.id===selectedFieldId);const props=document.getElementById('propsPanel');if(!q||!props)return;const assets=quizAssetsApi.getQuizAssets(editorQuiz.id);if(q.type==='image'){const box=document.createElement('div');box.innerHTML=`<h4>Upload local da imagem</h4><div class="field"><input id="fieldImageUpload" type="file" accept="image/jpeg,image/png,image/webp"><small class="muted">${imageTools.imageHint('content')}</small>${assets.fields[q.id]?`<img src="${assets.fields[q.id]}" alt="Prévia" style="width:100%;max-height:150px;object-fit:contain;margin-top:8px;border-radius:10px">`:''}</div>`;props.appendChild(box);document.getElementById('fieldImageUpload').onchange=async e=>{try{const r=await imageTools.validateImageFile(e.target.files[0],'content');quizAssetsApi.setFieldImage(editorQuiz.id,q.id,r.dataUrl);toast('Imagem do campo salva para preview local.','success');renderQuestionEditor();}catch(err){toast(err.message,'error');}};}
if(q.type==='image-options'&&q.options?.length){const box=document.createElement('div');box.innerHTML=`<h4>Imagens das opções</h4>${q.options.map((o,i)=>{const current=assets.options[`${q.id}:${o.id}`];return `<div class="field" style="margin-bottom:10px"><label>${escapeHtml(o.label||`Opção ${i+1}`)}</label><input type="file" data-option-upload="${o.id}" accept="image/jpeg,image/png,image/webp"><small class="muted">${imageTools.imageHint('option')}</small>${current?`<img src="${current}" alt="${escapeHtml(o.label)}" style="width:72px;height:72px;object-fit:cover;border-radius:9px;margin-top:6px">`:''}</div>`;}).join('')}`;props.appendChild(box);box.querySelectorAll('[data-option-upload]').forEach(el=>el.onchange=async()=>{try{const r=await imageTools.validateImageFile(el.files[0],'option');quizAssetsApi.setOptionImage(editorQuiz.id,q.id,el.dataset.optionUpload,r.dataUrl);toast('Imagem da opção salva para preview local.','success');renderQuestionEditor();}catch(err){toast(err.message,'error');}});}};

function openTemplatePreview(tpl){try{const q=quizAssetsApi.applyAssetsToPreview(deepClone(tpl.quiz));q.title=tpl.title||q.title;sessionStorage.setItem('qp_preview_draft',JSON.stringify(q));const url=`${publicBase()}/preview/`;modalRoot.innerHTML=`<div class="modal-backdrop"><section class="modal" style="width:min(1100px,96vw);max-height:94vh"><div class="modal-head"><div><strong>Preview do template</strong><div class="muted" style="font-size:12px">${escapeHtml(tpl.title)}</div></div><button class="icon-button" data-close-template>×</button></div><div class="modal-body" style="background:#e2e8f0"><iframe src="${url}" title="Preview do template" style="width:100%;height:700px;border:0;border-radius:14px;background:white"></iframe></div></section></div>`;modalRoot.querySelector('[data-close-template]').onclick=()=>modalRoot.innerHTML='';}catch(e){toast(`Falha ao abrir template: ${e.message}`,'error');}}
const _renderTemplatesBase=renderTemplates;
renderTemplates=function(){_renderTemplatesBase();content.querySelectorAll('.template-card').forEach((card,i)=>{if(card.querySelector('[data-preview-template]'))return;const btn=document.createElement('button');btn.className='btn btn-sm btn-ghost';btn.dataset.previewTemplate=String(i);btn.textContent='Pré-visualizar';btn.style.marginLeft='6px';btn.onclick=()=>openTemplatePreview(TEMPLATES[i]);card.appendChild(btn);});};

function profileCard(p,active){return `<article class="card" style="padding:14px;box-shadow:none"><div style="display:flex;gap:12px;align-items:center"><div style="width:46px;height:46px;border-radius:50%;background:var(--background);display:grid;place-items:center;overflow:hidden">${p.photoData?`<img src="${p.photoData}" alt="Perfil" style="width:100%;height:100%;object-fit:cover">`:`${escapeHtml((p.name||'U').charAt(0).toUpperCase())}`}</div><div style="flex:1"><strong>${escapeHtml(p.name)}</strong><small class="muted" style="display:block">${escapeHtml(p.email||'Sem e-mail')} · ${escapeHtml(p.role)}</small></div>${active?'<span class="status-pill success">Ativo</span>':''}</div><div class="actions" style="margin-top:10px"><button class="btn btn-sm btn-secondary" data-profile-edit="${p.id}">Editar</button>${!active?`<button class="btn btn-sm btn-ghost" data-profile-activate="${p.id}">Usar perfil</button>`:''}${p.id!=='owner'?`<button class="btn btn-sm btn-danger" data-profile-delete="${p.id}">Excluir</button>`:''}</div></article>`;}
function openProfileModal(profile=null){const p=profile||{id:`profile_${Date.now().toString(36)}`,name:'',email:'',role:'Editor',photoData:'',panelLogoData:''};modalRoot.innerHTML=`<div class="modal-backdrop"><section class="modal" style="max-width:560px"><div class="modal-head"><strong>${profile?'Editar perfil local':'Novo perfil local'}</strong><button class="icon-button" data-close-profile>×</button></div><div class="modal-body"><div class="field"><label>Nome</label><input id="profileName" value="${escapeHtml(p.name)}" maxlength="80"></div><div class="field"><label>E-mail de referência</label><input id="profileEmail" type="email" value="${escapeHtml(p.email)}"><small class="muted">Este e-mail é apenas identificação do perfil local. Não cria login.</small></div><div class="field"><label>Função</label><select id="profileRole"><option ${p.role==='Administrador'?'selected':''}>Administrador</option><option ${p.role==='Editor'?'selected':''}>Editor</option><option ${p.role==='Visualizador'?'selected':''}>Visualizador</option></select></div><div class="form-grid"><div class="field"><label>Foto de perfil</label><input id="profilePhoto" type="file" accept="image/jpeg,image/png,image/webp"><small class="muted">${imageTools.imageHint('profile')}</small></div><div class="field"><label>Logo pequena do painel</label><input id="profilePanelLogo" type="file" accept="image/jpeg,image/png,image/webp"><small class="muted">${imageTools.imageHint('panelLogo')}</small></div></div><p id="profileSpecificError" style="color:var(--danger);font-size:12px"></p></div><div class="modal-foot"><button class="btn btn-secondary" data-close-profile>Cancelar</button><button class="btn btn-primary" id="saveProfileLocal">Salvar perfil</button></div></section></div>`;modalRoot.querySelectorAll('[data-close-profile]').forEach(b=>b.onclick=()=>modalRoot.innerHTML='');document.getElementById('saveProfileLocal').onclick=async()=>{const err=document.getElementById('profileSpecificError');try{const next={...p,name:document.getElementById('profileName').value.trim(),email:document.getElementById('profileEmail').value.trim(),role:document.getElementById('profileRole').value};if(!next.name)throw new Error('Informe o nome do perfil.');const photo=document.getElementById('profilePhoto').files[0],logo=document.getElementById('profilePanelLogo').files[0];if(photo)next.photoData=(await imageTools.validateImageFile(photo,'profile')).dataUrl;if(logo)next.panelLogoData=(await imageTools.validateImageFile(logo,'panelLogo')).dataUrl;safeSettingsApi.saveProfile(next);modalRoot.innerHTML='';applyActiveProfile();toast('Perfil local salvo.','success');renderSettings();}catch(e){err.textContent=e.message;}};}

const _renderSettingsWithMemory=renderSettings;
renderSettings=async function(){await _renderSettingsWithMemory();const s=safeSettingsApi.getSafeSettings();const active=safeSettingsApi.getActiveProfile();const wrap=document.createElement('div');wrap.style.marginTop='18px';wrap.innerHTML=`<div class="settings-grid"><section class="card settings-card"><h3>Privacidade e Termos</h3><p class="muted" style="font-size:12px">Links exibidos no rodapé público e enviados com o quiz na próxima publicação.</p><div class="field"><label>Link da Política de Privacidade</label><input id="privacyUrlSafe" value="${escapeHtml(s.legal.privacyUrl)}" placeholder="https://seusite.com/politica-de-privacidade"></div><div class="field"><label>Link dos Termos de Uso</label><input id="termsUrlSafe" value="${escapeHtml(s.legal.termsUrl)}" placeholder="https://seusite.com/termos-de-uso"></div><div class="field"><label>Texto da concordância</label><textarea id="consentTextSafe">${escapeHtml(s.legal.consentText)}</textarea></div><div class="field-row"><span>Exigir concordância antes de concluir</span><label class="toggle"><input id="consentRequiredSafe" type="checkbox" ${s.legal.consentRequired?'checked':''}><span></span></label></div><button class="btn btn-primary" id="saveLegalSafe" style="margin-top:14px">Salvar políticas</button><div class="code-box" style="margin-top:12px">A política padrão permanece visível em todos os quizzes e formulários públicos.</div></section><section class="card settings-card"><div class="section-head"><div><h3 style="margin:0">Perfis do painel</h3><p>Perfis locais de trabalho</p></div><button class="btn btn-secondary" id="newLocalProfile">+ Novo perfil</button></div><div style="display:grid;gap:10px">${s.profiles.map(p=>profileCard(p,p.id===active?.id)).join('')}</div><div class="code-box" style="margin-top:14px">Por segurança, estes perfis não são contas de login. Criar usuários reais exige alterar o sistema de autenticação/backend.</div></section></div>`;content.appendChild(wrap);document.getElementById('saveLegalSafe').onclick=()=>{try{safeSettingsApi.saveLegal({privacyUrl:document.getElementById('privacyUrlSafe').value.trim(),termsUrl:document.getElementById('termsUrlSafe').value.trim(),consentText:document.getElementById('consentTextSafe').value.trim(),consentRequired:document.getElementById('consentRequiredSafe').checked});toast('Políticas salvas. Publique novamente o quiz para enviar a configuração personalizada.','success');}catch(e){toast(e.message,'error');}};document.getElementById('newLocalProfile').onclick=()=>openProfileModal();content.querySelectorAll('[data-profile-edit]').forEach(b=>b.onclick=()=>openProfileModal(s.profiles.find(p=>p.id===b.dataset.profileEdit)));content.querySelectorAll('[data-profile-activate]').forEach(b=>b.onclick=()=>{try{safeSettingsApi.setActiveProfile(b.dataset.profileActivate);applyActiveProfile();toast('Perfil ativo alterado.','success');renderSettings();}catch(e){toast(e.message,'error');}});content.querySelectorAll('[data-profile-delete]').forEach(b=>b.onclick=()=>{try{if(confirm('Excluir este perfil local?')){safeSettingsApi.removeProfile(b.dataset.profileDelete);applyActiveProfile();renderSettings();}}catch(e){toast(e.message,'error');}});};

