async function applyAuthenticatedAvatar(){
  const avatar=document.getElementById('accountAvatar')||document.querySelector('.avatar');
  if(!avatar)return;
  const localProfile=safeSettingsApi.getActiveProfile();
  let user=null;
  try{user=await accountAuth.currentUser();}catch{}
  const photo=localProfile?.photoData||user?.photoURL||'';
  const name=localProfile?.name||user?.displayName||'Wakilon Gestor';
  if(photo)avatar.innerHTML=`<img src="${escapeHtml(photo)}" alt="Foto de ${escapeHtml(name)}" style="width:100%;height:100%;object-fit:cover;border-radius:50%">`;
  else avatar.textContent=name.split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase();
  avatar.title='Abrir menu da conta';
}

function closeAccountMenu(){document.getElementById('qpAccountMenu')?.remove();}
async function openAccountMenu(e){
  e?.stopPropagation();
  const existing=document.getElementById('qpAccountMenu');if(existing){existing.remove();return;}
  const profile=safeSettingsApi.getActiveProfile();let user=null;try{user=await accountAuth.currentUser();}catch{}
  const name=profile?.name||user?.displayName||'Wakilon Gestor';const email=user?.email||profile?.email||accountAuth.ADMIN_EMAIL;const photo=profile?.photoData||user?.photoURL||'';
  const menu=document.createElement('div');menu.id='qpAccountMenu';menu.style='position:fixed;right:22px;top:72px;width:min(330px,calc(100vw - 28px));background:var(--surface);border:1px solid var(--border);border-radius:16px;box-shadow:0 22px 60px rgba(15,23,42,.18);padding:12px;z-index:3000';
  menu.innerHTML=`<div style="display:flex;gap:12px;align-items:center;padding:8px 8px 14px;border-bottom:1px solid var(--border)"><div style="width:48px;height:48px;border-radius:50%;overflow:hidden;background:var(--background);display:grid;place-items:center">${photo?`<img src="${escapeHtml(photo)}" alt="Perfil" style="width:100%;height:100%;object-fit:cover">`:escapeHtml(name.charAt(0).toUpperCase())}</div><div style="min-width:0"><strong style="display:block">${escapeHtml(name)}</strong><small class="muted" style="display:block;overflow:hidden;text-overflow:ellipsis">${escapeHtml(email)}</small></div></div><div style="display:grid;gap:6px;padding-top:10px"><button class="btn btn-ghost" data-account-action="settings" style="justify-content:flex-start">⚙️ Perfil e Configurações</button><button class="btn btn-ghost" data-account-action="integrations" style="justify-content:flex-start">🔌 Conexões e Apps</button><button class="btn btn-danger" data-account-action="logout" style="justify-content:flex-start">↪ Sair</button></div>`;
  document.body.appendChild(menu);
  menu.querySelector('[data-account-action="settings"]').onclick=()=>{closeAccountMenu();navigate('settings');};
  menu.querySelector('[data-account-action="integrations"]').onclick=()=>{closeAccountMenu();navigate('integrations');};
  menu.querySelector('[data-account-action="logout"]').onclick=async()=>{closeAccountMenu();await logout();location.reload();};
}
const accountAvatar=document.getElementById('accountAvatar')||document.querySelector('.avatar');if(accountAvatar){accountAvatar.onclick=openAccountMenu;}document.addEventListener('click',e=>{if(!e.target.closest('#qpAccountMenu')&&!e.target.closest('#accountAvatar'))closeAccountMenu();});
